// OpenAPI -> contracts/honto-api.ts (types + operations map). Do not edit the output by hand.
import { describe, operations, schemaKind, typeName } from "./spec.mjs";

const doc = (text, indent = "") => (text ? `${indent}/** ${String(text).trim().replace(/\*\//g, "*\\/").replace(/\n+/g, ` */\n${indent}/** `)} */\n` : "");

function tsType(d) {
  let t;
  switch (d.kind) {
    case "ref": t = typeName(d.name); break;
    case "array": t = `Array<${tsType(d.items)}>`; break;
    case "map": t = `Record<string, ${tsType(d.values)}>`; break;
    case "unknown": return "unknown";
    case "datetime": t = "IsoDateTime"; break;
    case "string": t = "string"; break;
    case "int": case "double": t = "number"; break;
    case "bool": t = "boolean"; break;
    default: throw new Error(d.kind);
  }
  return d.nullable ? `${t} | null` : t;
}

export function generateTs(spec) {
  const lines = [
    "// GENERATED by contracts/scripts/generate.mjs from contracts/openapi.yaml. Do not edit by hand.",
    "// Run `npm run contracts:generate` after changing the spec; `npm run contracts:check` fails on drift.",
    "",
    "/** RFC 3339 timestamp in UTC, e.g. 2026-10-19T15:04:05Z. */",
    "export type IsoDateTime = string;",
    "",
  ];
  for (const [name, schema] of Object.entries(spec.components.schemas)) {
    const tn = typeName(name);
    const kind = schemaKind(schema);
    { const c = doc(schema.description); if (c) lines.push(c.trimEnd()); }
    if (kind === "enum") {
      lines.push(`export const ${tn}Values = [${schema.enum.map((v) => JSON.stringify(v)).join(", ")}] as const;`);
      lines.push(`export type ${tn} = (typeof ${tn}Values)[number];`);
    } else if (kind === "alias") {
      lines.push(`export type ${tn} = ${tsType(describe(schema))};`);
    } else {
      lines.push(`export interface ${tn} {`);
      const required = new Set(schema.required ?? []);
      for (const [prop, ps] of Object.entries(schema.properties ?? {})) {
        const d = describe(ps);
        { const c = doc(ps.description, "  "); if (c) lines.push(c.trimEnd()); }
        lines.push(`  ${/^[A-Za-z_$][\w$]*$/.test(prop) ? prop : JSON.stringify(prop)}${required.has(prop) ? "" : "?"}: ${tsType(d)};`);
      }
      if (schema.additionalProperties === true) lines.push("  [extra: string]: unknown;");
      lines.push("}");
    }
    lines.push("");
  }
  const ops = operations(spec);
  lines.push("/** Every operation of the API, keyed by operationId. */");
  lines.push("export interface Operations {");
  for (const op of ops) {
    const pathParams = op.pathParams.length ? `{ ${op.pathParams.map((p) => `${p.name}: string`).join("; ")} }` : "never";
    const query = op.queryParams.length ? `{ ${op.queryParams.map((p) => `${p.name}${p.required ? "" : "?"}: string`).join("; ")} }` : "never";
    const body = op.body ? typeName(op.body) : "never";
    const responses = Object.entries(op.responses).map(([s, n]) => `${s}: ${n ? typeName(n) : "void"}`).join("; ");
    { const c = doc(`${op.method} ${op.path}: ${op.summary}`, "  "); if (c) lines.push(c.trimEnd()); }
    lines.push(`  ${op.id}: { method: "${op.method}"; path: "${op.path}"; pathParams: ${pathParams}; query: ${query}; body: ${body}; responses: { ${responses} } };`);
  }
  lines.push("}");
  lines.push("");
  lines.push("export type OperationId = keyof Operations;");
  lines.push("/** Union of the 2xx bodies of an operation (void for 204/304). */");
  lines.push("export type SuccessBody<Op extends OperationId> = { [S in keyof Operations[Op][\"responses\"]]: S extends 200 | 201 | 202 | 204 ? Operations[Op][\"responses\"][S] : never }[keyof Operations[Op][\"responses\"]];");
  lines.push("");
  lines.push("/** Runtime route table (method + path template + whether it needs auth). */");
  lines.push("export const operations = {");
  for (const op of ops) lines.push(`  ${op.id}: { method: "${op.method}", path: "${op.path}", auth: ${JSON.stringify(op.security.length ? op.security.flatMap((s) => Object.keys(s)) : [])} },`);
  lines.push("} as const satisfies Record<OperationId, { method: string; path: string; auth: readonly string[] }>;");
  lines.push("");
  return lines.filter((l, i, a) => !(l === "" && a[i - 1] === "")).join("\n");
}
